package dev.lumenchess.board

import dev.lumenchess.core.chess.PieceType

/** The six approved P6.1 Direction-A / A-S2 master silhouettes. */
enum class LumenPieceKind {
    PAWN,
    ROOK,
    KNIGHT,
    BISHOP,
    QUEEN,
    KING,
}

/** Piece-specific optical calibration measured in a 160 px board square. */
data class LumenPieceOptics(
    val fillWidthAt160: Float,
    val fillHeightAt160: Float,
    val xOffsetAt160: Float,
    val baselineAt160: Float,
)

data class LumenPieceBounds(
    val left: Float,
    val top: Float,
    val right: Float,
    val bottom: Float,
) {
    val width: Float get() = right - left
    val height: Float get() = bottom - top
}

data class LumenPieceSpec(
    val optics: LumenPieceOptics,
    val contours: List<FloatArray>,
) {
    /** Includes the restrained one-pixel-at-160 contour around the master fill. */
    fun paintedBounds(squarePx: Float): LumenPieceBounds {
        val scale = squarePx / 160f
        val fillWidth = optics.fillWidthAt160 * scale
        val fillHeight = optics.fillHeightAt160 * scale
        val edgeRadius = scale
        val left = (squarePx - fillWidth) / 2f + optics.xOffsetAt160 * scale
        val top = (optics.baselineAt160 - optics.fillHeightAt160) * scale
        return LumenPieceBounds(
            left = left - edgeRadius,
            top = top - edgeRadius,
            right = left + fillWidth + edgeRadius,
            bottom = optics.baselineAt160 * scale + edgeRadius,
        )
    }
}

